## JavaScript 코드
```JavaScript
const _arr = [1, 3, 7, 8, 4, 3, 5, 2, 9, 2];

function g(a, b, x) {
    let c = 0;

    for (let i = a; i <= b; i++) {
        if (_arr[i] <= x) {
            c += 1;
        }
    }

    return c;
}

function f(a, b, x, k) {
    if (a === b) {
        return _arr[a];
    }

    let mid = parseInt((a + b) / 2);
    let lc = g(a, mid, x);

    if (lc >= k) return f(a, mid, x, k);
    else return f(mid + 1, b, x, k - lc);
}
